import { compareOptions, getSelectValue, transform } from "./utils.js";
import { isEmpty } from "../core/utils/string.js";
export default {
    tag: "f-relation-list",
    jsImport: "lume_cms/components/f-relation-list.js",
    async init(field, cmsContent) {
        if (field.options?.length) {
            return;
        }
        const collection = cmsContent.collections[field.collection];
        if (!collection) {
            throw new Error(`Collection '${field.collection}' not found for relation field '${field.name}'`);
        }
        const createOption = field.option ??
            (({ label, name }) => ({
                label,
                value: name,
            }));
        field.options = (await Array.fromAsync(collection)).map(createOption).sort(compareOptions);
    },
    applyChanges(data, changes, field) {
        const options = field.options;
        const value = Object.values(changes[field.name] || {})
            .map((value) => getSelectValue(options, value))
            .filter((v) => !isEmpty(v));
        data[field.name] = transform(field, value);
    },
};
